-- Nihongo Labs N5 vocabulary seed: 500 selected entries.
-- Adapted from OpenJLPT (CC BY-SA 4.0); see ../docs/VOCABULARY_CONTENT_PACK.md.
-- Tatoeba example sentence IDs are preserved in tags as source:tatoeba:<id>.
-- JLPT level assignment is a community approximation, not an official current JLPT list.
-- New rows are held at publication_status='review' for editorial QA.
begin;

on conflict (jlpt_level,word,kana) do update set
  romaji=excluded.romaji,
  meaning=excluded.meaning,
  part_of_speech=excluded.part_of_speech,
  example_sentence=coalesce(excluded.example_sentence, public.vocabulary_entries.example_sentence),
  example_reading=coalesce(excluded.example_reading, public.vocabulary_entries.example_reading),
  example_translation=coalesce(excluded.example_translation, public.vocabulary_entries.example_translation),
  tags=excluded.tags,
  publication_status=case when public.vocabulary_entries.publication_status='published' then 'published'::public.publication_status else excluded.publication_status end,
  updated_at=now();

commit;
